SELECT DISTINCT s.*
FROM wkf_schedule s
LEFT JOIN wkf_schedule_actor a ON s.id = a.schedule_id AND a.is_deleted = 0
WHERE s.is_deleted = 0

    AND s.organization_id = #{query.organizationId}


    AND s.healthcare_service_id = #{query.healthcareServiceId}


    AND a.actor_id = #{query.practitionerId}


    AND s.planning_horizon_end >= #{query.rangeStart}


    AND s.planning_horizon_start <= #{query.rangeEnd}


    AND s.organization_id = #{query.locationId}

ORDER BY s.planning_horizon_start

SELECT * FROM wkf_schedule_actor WHERE is_deleted = 0 AND schedule_id IN
#{id}
ORDER BY sort_no
